text:
{
  "title": "سياسة الخصوصية وشروط الاستخدام لشركة الأفق الرقمي للخدمات التقنية",
  "planted": [
    {
      "slot": "p1",
      "text": "في حال وقوع أي حادث أمني أو وصول غير مصرح به إلى الأنظمة، تباشر الشركة تقييم الوضع داخلياً، ويجوز لها عند اقتضاء الحاجة وفقاً لتقديرها التجاري البحت إشعار الجهات المختصة أو المستخدم المتأثر ضمن جدول زمني مناسب يتم تحديده بحسب الظروف التشغيلية ودون الارتباط بمدد محددة."
    },
    {
      "slot": "p2",
      "text": "تحتفظ الشركة بجميع السجلات والبيانات المدخلة في قواعد بياناتها لفترات زمنية ممتدة وغير محدودة، لضمان استمرارية الخدمات والرجوع إليها تاريخياً عند الحاجة المستقبلية، حيث تظل تلك البيانات محفوظة في ارشيفنا الرقمي دون التزام بإزالتها أو التخلص منها."
    },
    {
      "slot": "p3",
      "text": "يُعتبر مجرد تصفح الموقع أو الاستمرار في الاستفادة من الخدمات إقراراً ضمنياً وموافقة لا رجعة فيها على كافة أساليب معالجة البيانات واستخدامها، ولا يحق للمستخدم طلب إلغاء هذه الموافقة أو تقييدها طالما كان الحساب نشطاً أو خلال أي فترة سابقة."
    },
    {
      "slot": "p4",
      "text": "تقتصر أغراض معالجة البيانات التي تجمعها الشركة حصرياً على الأغراض التشغيلية المرتبطة بتقديم الخدمات وتحسين تجربة العميل، دون استخدامها في أي مسارات أخرى غير معلنة."
    },
    {
      "slot": "p5",
      "text": "يحق للمستخدمين التواصل معنا لتقديم طلبات تتعلق بالاستفسار عن طبيعة المعلومات المحفوظة لدينان أو طلب مراجعتها وإجراء ما يلزم بشأنها وفقاً للآليات الداخلية المعتمدة لدى إدارة خدمة العملاء."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية وأتعاب الخدمات المقدمة للشروط والأحكام المحددة في فواتير الدفع الإلكتروني الصادرة، والتي يجب سدادها في مواعيدها المقررة لضمان عدم توقف الخدمة.",
    "تبدأ المدة التعاقدية لهذه الاتفاقية فور إتمام التسجيل وتستمر حتى قيام أحد الطرفين بإنهاء التعاقد وفقاً للإجراءات النظامية المتبعة.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن أي أضرار غير مباشرة أو تبعية قدל ت نشأ نتيجة انقطاع الخدمة أو تعطل الشبكات لأسباب خارجة عن إرادتها التشغيلية.",
    "تخضع هذه الشروط والأحكام للأنظمة المعمول بها في المملكة العربية السعودية، وتختص المحاكم المختصة بالفصل في أي نزاع ينشأ عنها.",
    "جميع حقوق الملكية الفكرية المتعلقة بالتصميمات والعلامات التجارية والبرمجيات المستخدمة هي ملك حصري للشركة، ولا يجوز نسخها أو استخدامها بدون إذن كتابي مسبق.",
    "تتم كافة الإشعارات الرسمية المتبادلة بين الطرفين عبر البريد الإلكتروني المسجل في الحساب أو من خلال الرسائل النصية المعتمدة."
  ]
}
